package com.fooddelivery.controller; import com.fooddelivery.model.*; import com.fooddelivery.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/restaurants") public class RestaurantController { final RestaurantRepository rr; final MenuItemRepository mr; RestaurantController(RestaurantRepository r,MenuItemRepository m){rr=r;mr=m;} @GetMapping public List<Restaurant> all(){return rr.findAll();} @GetMapping("/{id}") public Restaurant one(@PathVariable Long id){return rr.findById(id).orElseThrow();} @GetMapping("/{id}/menu") public List<MenuItem> menu(@PathVariable Long id){return mr.findByRestaurantId(id);} }